pub fn get_area(id: u32) -> Option<&'static AreaInfo> {
    AREA_DB.get(&id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_area_count() {
        assert!(AREA_DB.len() > 5000);
    }

    #[test]
    fn test_stormwind_city() {
        let area = get_area(1519).expect("Stormwind City (1519) should exist");
        assert_eq!(area.name, "Stormwind City");
        assert_eq!(area.parent_area_id, 0);
    }

    #[test]
    fn test_trade_district() {
        let area = get_area(5148).expect("Trade District (5148) should exist");
        assert_eq!(area.name, "Trade District");
        assert_eq!(area.parent_area_id, 1519);
    }

    #[test]
    fn test_nonexistent_area() {
        assert!(get_area(999_999_999).is_none());
    }
}
